head.b:skin:
/*
<Group description="CleanPress Lite Colors">
  <Variable name="cp.bg" description="Background" type="color" default="#f8fafc" value="#f8fafc"/>
  <Variable name="cp.surface" description="Card Surface" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="cp.ink" description="Main Text" type="color" default="#0f172a" value="#0f172a"/>
  <Variable name="cp.muted" description="Secondary Text" type="color" default="#475569" value="#475569"/>
  <Variable name="cp.border" description="Border Color" type="color" default="#e2e8f0" value="#e2e8f0"/>
  <Variable name="cp.accent" description="Brand Accent" type="color" default="#4f46e5" value="#4f46e5"/>
</Group>
*/
:root { --bg:$(cp.bg); --surface:$(cp.surface); --ink:$(cp.ink); --muted:$(cp.muted); --border:$(cp.border); --accent:$(cp.accent); }
html[data-theme='dark'] { --bg:#070b14; --surface:#0f172a; --ink:#f8fafc; --muted:#94a3b8; --border:#1e293b; --accent:#6366f1; }
* { box-sizing:border-box; margin:0; padding:0; }
body { background:var(--bg); color:var(--ink); font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif; line-height:1.65; }
a { color:inherit; text-decoration:none; }
.cp-wrap { max-width:1120px; margin:0 auto; padding:0 20px; }
.cp-head { position:sticky; top:0; z-index:40; background:var(--surface); border-bottom:1px solid var(--border); }
.cp-head-in { min-height:66px; display:flex; align-items:center; justify-content:space-between; gap:16px; }
.cp-brand { font-size:1.25rem; font-weight:800; letter-spacing:-0.02em; }
.cp-layout { display:grid; grid-template-columns:1fr 300px; gap:28px; padding:32px 0 48px; align-items:start; }
.cp-post-card { background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:22px; margin-bottom:18px; }
.cp-post-card h2 { font-size:1.3rem; font-weight:800; line-height:1.3; margin-bottom:8px; }
.cp-meta { font-size:0.8rem; color:var(--muted); margin-bottom:10px; font-weight:600; }
.cp-snippet { color:var(--muted); font-size:0.95rem; margin-bottom:14px; }
.cp-readmore { display:inline-block; color:var(--accent); font-weight:700; font-size:0.88rem; }
.cp-widget { background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:18px; margin-bottom:18px; }
.cp-widget h3 { font-size:0.95rem; font-weight:800; margin-bottom:10px; }
.cp-btn { padding:7px 12px; border-radius:8px; border:1px solid var(--border); background:var(--bg); color:var(--ink); font-weight:700; font-size:0.82rem; cursor:pointer; }
.cp-foot { border-top:1px solid var(--border); padding:24px 0; text-align:center; color:var(--muted); font-size:0.85rem; }
@media (max-width:860px) { .cp-layout { grid-template-columns:1fr; } }

body.script:
//
    (function(){
      var key='cp_theme';
      function apply(t){ document.documentElement.setAttribute('data-theme', t); localStorage.setItem(key,t); }
      apply(localStorage.getItem(key)||'light');
      var btn=document.getElementById('cpThemeBtn');
      if(btn){ btn.addEventListener('click', function(){ apply(document.documentElement.getAttribute('data-theme')==='dark'?'light':'dark'); }); }
    })();
  //
